using GraphApi.Models.SGR.Perfiles;namespace GraphApi.Services.SGR.Perfiles{    /// <summary>    /// Define las operaciones de negocio y persistencia para Perfiles.    /// </summary>    public interface IPerfilesService    {        /// <summary>        /// Obtiene la lista de Perfiles con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadPerfiles>> GetPerfiles(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Perfiles con filtros opcionales.        /// </summary>        /// <param name="perfilID">Filtro opcional para PerfilID.</param>        /// <param name="perfil">Filtro opcional para Perfil.</param>        /// <param name="descripcion">Filtro opcional para Descripcion.</param>        /// <param name="bAdministrador">Filtro opcional para bAdministrador.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="usuariosAsignados">Filtro opcional para UsuariosAsignados.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetPerfilesDynamic(            int? perfilID,            string? perfil,            string? descripcion,            bool? bAdministrador,            bool? bEliminado,            int? usuariosAsignados,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Perfile.        /// </summary>        /// <param name="objInput">Datos para crear el Perfile.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadPerfiles> CreatePerfiles(            clCreatePerfiles objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Perfile.        /// </summary>        /// <param name="objInput">Datos para actualizar el Perfile, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadPerfiles?> UpdatePerfiles(            clUpdatePerfiles objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Perfile por su ID.        /// </summary>        /// <param name="nPerfilesID">ID del Perfile a eliminar.</param>        Task<bool> DeletePerfiles(int nPerfilesID);    }}